package com.loopers.domain.productlike

import com.loopers.domain.product.Product
import com.loopers.domain.product.ProductRepository
import com.loopers.domain.user.User
import com.loopers.domain.user.UserRepository
import com.loopers.support.error.CoreException
import com.loopers.support.error.ErrorType
import org.springframework.data.domain.Page
import org.springframework.data.domain.Pageable
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional

@Service
@Transactional\(readOnly = true\)
class ProductLikeService\(
    private val productLikeRepository: ProductLikeRepository,
    private val productRepository: ProductRepository,
    private val userRepository: UserRepository,
\) {

    @Transactional
    fun likeProduct\(userId: Long, productId: Long\) {
        // 이미 좋아요한 상품인지 확인
        if \(productLikeRepository.existsByUserIdAndProductId\(userId, productId\)\) {
            throw CoreException\(ErrorType.BAD_REQUEST, "이미 좋아요한 상품입니다."\)
        }

        // User와 Product 조회
        val user = userRepository.findById\(userId\)
        val product = productRepository.findById\(productId\)

        // ProductLike 생성 및 저장
        val productLike = ProductLike.create\(user, product\)
        productLikeRepository.save\(productLike\)

        // Product의 좋아요 수 증가
        product.incrementLikeCount\(\)
    }

    @Transactional
    fun unlikeProduct\(userId: Long, productId: Long\) {
        // ProductLike 조회
        val productLike = productLikeRepository.findByUserIdAndProductId\(userId, productId\)
            ?: throw CoreException\(ErrorType.NOT_FOUND, "좋아요 기록이 존재하지 않습니다."\)

        // ProductLike 삭제
        productLikeRepository.delete\(productLike\)

        // Product의 좋아요 수 감소
        val product = productRepository.findById\(productId\)
        product.decrementLikeCount\(\)
    }

    fun getMyLikedProducts\(userId: Long, pageable: Pageable\): Page<ProductLike> {
        return productLikeRepository.findByUserId\(userId, pageable\)
    }
}
