package com.loopers.application.productlike

import com.loopers.domain.product.ProductRepository
import com.loopers.domain.productlike.ProductLikeService
import com.loopers.domain.user.UserRepository
import com.loopers.support.error.CoreException
import com.loopers.support.error.ErrorType
import org.springframework.data.domain.Page
import org.springframework.data.domain.Pageable
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional

/**
 * 상품 좋아요 Facade
 * 비즈니스 로직 조합: User, Product, ProductLike 도메인 통합
 * - User와 Product 존재 확인
 * - ProductLike 관리 \(ProductLikeService\)
 * - Product 카운터 동기화
 */
@Service
@Transactional\(readOnly = true\)
class ProductLikeFacade\(
    private val productLikeService: ProductLikeService,
    private val productRepository: ProductRepository,
    private val userRepository: UserRepository,
\) {

    @Transactional
    fun likeProduct\(userId: Long, productId: Long\) {
        // User 존재 확인
        val user = userRepository.findUserById\(userId\)
            ?: throw CoreException\(ErrorType.NOT_FOUND, "사용자가 존재하지 않습니다."\)

        // Product 존재 확인
        val product = productRepository.findById\(productId\)

        // 이미 좋아요했는지 확인 \(멱등성\)
        val isNewLike = productLikeService.findByUserIdAndProductId\(userId, productId\) == null

        // ProductLike 추가 \(멱등성 있음\)
        productLikeService.addProductLike\(user, product\)

        // 새로운 좋아요인 경우만 카운터 증가
        if \(isNewLike\) {
            product.incrementLikeCount\(\)
        }
    }

    @Transactional
    fun unlikeProduct\(userId: Long, productId: Long\) {
        // User 존재 확인
        val user = userRepository.findUserById\(userId\)
            ?: throw CoreException\(ErrorType.NOT_FOUND, "사용자가 존재하지 않습니다."\)

        // Product 존재 확인
        val product = productRepository.findById\(productId\)

        // 좋아요 기록 확인 \(멱등성\)
        val hasLike = productLikeService.findByUserIdAndProductId\(userId, productId\) != null

        // ProductLike 삭제 \(멱등성 있음\)
        productLikeService.removeProductLike\(user, product\)

        // 좋아요가 있었던 경우만 카운터 감소
        if \(hasLike\) {
            product.decrementLikeCount\(\)
        }
    }

    fun getMyLikedProducts\(userId: Long, pageable: Pageable\) {
        // User 존재 확인
        userRepository.findUserById\(userId\)
            ?: throw CoreException\(ErrorType.NOT_FOUND, "사용자가 존재하지 않습니다."\)
    }

    fun getMyLikedProductDetails\(userId: Long, pageable: Pageable\) = 
        productLikeService.getMyLikedProductDetails\(userId, pageable\)
}
